out=["# Content drafts: weeks 2-8 (status: DRAFT, needs your review)\n","Rules: change anything that doesn't sound like you. Delete any line you can't back up. Post only what's true.\nFace videos = teleprompter scripts (2 per week). Animated = faceless storyboards (2 per week).\nEvery caption ends with: *Drafted with AI, reviewed and edited by me.* (check each platform's AI-label rules)\nReplace [LINK] once the landing page exists.\n","Honesty checks that apply to every post: say 'my route / my experience', not 'the way'; no promised outcomes; no health claims beyond 'talk to a professional'; no private details about your parents, brothers or other families; keep proof ready.\n"]
for wk,(theme,sub,posts) in W.items():
    out.append(f"\n---\n\n# Week {wk}: {theme}\n*{sub}*\n")
    for i,p in enumerate(posts,1):
        if p["t"]=="face":
            out.append(f"\n## Week {wk}, Post {i}: FACE VIDEO (teleprompter)\n**HOOK TEXT:** {p['hook']}\n\nScript:\n"+"\n".join(p["lines"])+f"\n\n**B-roll / overlay:** {'; '.join(p['broll'])}\n**Caption:** {p['cap']}\n*Drafted with AI, reviewed and edited by me.*\n")
        else:
            sc="\n".join(f"SCENE {n} ({s}s) | NARRATION: {nar} | VISUAL: {vis} | ON-SCREEN TEXT: {txt}" for n,(s,nar,vis,txt) in enumerate(p["scenes"],1))
            out.append(f"\n## Week {wk}, Post {i}: ANIMATED (faceless)\n**HOOK TEXT:** {p['hook']}\n\n{sc}\n\n**Caption:** {p['cap']}\n*Drafted with AI, reviewed and edited by me.*\n")
        if p.get("note"): out.append(f"**NOTE FOR YOU:** {p['note']}\n")
import os; open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "weeks_02_to_08.md"),"w").write("\n".join(out))
print(sum(len(p) for *_,p in W.values()),"posts")
